"""`pdf_meta.creation_date` (D3 §5.6, §13). Every PDF is generated by `make_pdf` or edited from its output."""

import zlib
from datetime import UTC, datetime, timedelta, timezone

import pytest

from energatron.adapters.sources import pdf_meta
from energatron.adapters.sources.pdf_meta import creation_date
from tests.fixtures.make_sources import make_pdf

PLAIN = datetime(2025, 3, 4, 5, 6, 7)


def tz(hours: int, minutes: int = 0) -> timezone:
    sign = -1 if hours < 0 else 1
    return timezone(sign * timedelta(hours=abs(hours), minutes=minutes))


def test_a_plain_literal_date() -> None:
    assert creation_date(make_pdf(creation_date="D:20250304050607")) == PLAIN


def test_the_d_prefix_is_optional() -> None:
    assert creation_date(make_pdf(creation_date="20250304050607")) == PLAIN


def test_an_escaped_literal_date() -> None:
    data = make_pdf(creation_date="D:20250304050607")
    escaped = data.replace(b"(D:2025", b"(D:\\062025\\\n", 1)  # an octal escape and a line continuation
    assert escaped != data
    assert creation_date(escaped) == PLAIN


def test_a_hex_date() -> None:
    data = make_pdf(creation_date="D:20250304050607", date_encoding="hex")
    assert b"(D:" not in data
    assert creation_date(data) == PLAIN


def test_a_utf16be_date() -> None:
    data = make_pdf(creation_date="D:20250304050607", date_encoding="utf16")
    assert b"\xfe\xff" in data
    assert creation_date(data) == PLAIN


def test_an_info_dictionary_in_a_compressed_object_stream() -> None:
    data = make_pdf(creation_date="D:20250304050607Z", info_in_objstm=True)
    assert b"/CreationDate" not in data
    assert creation_date(data) == PLAIN.replace(tzinfo=UTC)


def test_plain_and_compressed_xmp() -> None:
    for compressed in (False, True):
        data = make_pdf(creation_date=None, xmp="2025-03-04T05:06:07+10:30", xmp_compressed=compressed)
        assert (b"CreateDate" in data) is not compressed
        assert creation_date(data) == PLAIN.replace(tzinfo=tz(10, 30))


def test_xmp_as_an_attribute() -> None:
    data = make_pdf(creation_date=None, xmp="X")
    data = data.replace(b"<xmp:CreateDate>X</xmp:CreateDate>", b"").replace(
        b'rdf:about=""', b"rdf:about=\"\" xmp:CreateDate='2025-03-04T05:06:07'"
    )
    assert creation_date(data) == PLAIN


def test_xmp_without_an_offset_is_naive_and_a_date_alone_is_midnight() -> None:
    assert creation_date(make_pdf(creation_date=None, xmp="2025-03-04T05:06:07")) == PLAIN
    assert creation_date(make_pdf(creation_date=None, xmp="2025-03-04")) == datetime(2025, 3, 4)


def test_creation_date_comes_before_xmp() -> None:
    data = make_pdf(creation_date="D:20250304050607", xmp="2020-01-01T00:00:00")
    assert creation_date(data) == PLAIN


@pytest.mark.parametrize(
    ("suffix", "zone"),
    [("Z", UTC), ("+10'30'", tz(10, 30)), ("-05'00'", tz(-5)), ("+09", tz(9)), ("Z00'00'", UTC), ("", None)],
)
def test_offsets(suffix: str, zone: timezone | None) -> None:
    found = creation_date(make_pdf(creation_date=f"D:20250304050607{suffix}"))
    assert found == PLAIN.replace(tzinfo=zone)
    assert (found is not None and found.tzinfo is None) is (zone is None)


@pytest.mark.parametrize(
    ("value", "expected"),
    [
        ("D:2025", datetime(2025, 1, 1)),
        ("D:202503", datetime(2025, 3, 1)),
        ("D:20250304", datetime(2025, 3, 4)),
        ("D:2025030405", datetime(2025, 3, 4, 5)),
        ("D:202503040506", datetime(2025, 3, 4, 5, 6)),
    ],
)
def test_a_truncated_date_is_filled_with_defaults(value: str, expected: datetime) -> None:
    assert creation_date(make_pdf(creation_date=value)) == expected


def test_an_invalid_date_is_skipped_for_a_later_valid_one() -> None:
    data = make_pdf(creation_date="D:20251399000000", xmp="2025-03-04T05:06:07")
    assert creation_date(data) == PLAIN


def test_a_stream_that_fails_to_inflate_is_skipped() -> None:
    good = make_pdf(creation_date="D:20250304050607Z", info_in_objstm=True)
    broken = b"9 0 obj\n<< /Filter /FlateDecode /Length 8 >>\nstream\nnot-zlib\nendstream\nendobj\n"
    data = good.replace(b"1 0 obj", broken + b"1 0 obj", 1)
    assert creation_date(data) == PLAIN.replace(tzinfo=UTC)


def test_a_stream_with_another_filter_is_not_inflated() -> None:
    packet = zlib.compress(b"<< /CreationDate (D:20250304050607) >>")
    stream = b"<< /Filter [/FlateDecode /ASCIIHexDecode] /Length 1 >>\nstream\n" + packet + b"\nendstream"
    assert creation_date(b"%PDF-1.5\n" + stream + b"\n%%EOF\n") is None
    single = stream.replace(b"[/FlateDecode /ASCIIHexDecode]", b"[ /FlateDecode ]")
    assert creation_date(b"%PDF-1.5\n" + single + b"\n%%EOF\n") == PLAIN


def test_no_date_is_none() -> None:
    assert creation_date(make_pdf(creation_date=None)) is None
    assert creation_date(b"") is None
    assert creation_date(b"%PDF-1.4\n/CreationDate (not a date)\n%%EOF") is None


def test_the_inflate_limit_stops_the_search() -> None:
    good = make_pdf(creation_date="D:20250304050607Z", info_in_objstm=True)
    big = zlib.compress(bytes(pdf_meta.INFLATE_LIMIT + 1), 9)
    bomb = b"9 0 obj\n<< /Filter /FlateDecode >>\nstream\n" + big + b"\nendstream\nendobj\n"
    assert creation_date(good.replace(b"1 0 obj", bomb + b"1 0 obj", 1)) is None
    small = zlib.compress(bytes(1024), 9)
    harmless = b"9 0 obj\n<< /Filter /FlateDecode >>\nstream\n" + small + b"\nendstream\nendobj\n"
    assert creation_date(good.replace(b"1 0 obj", harmless + b"1 0 obj", 1)) == PLAIN.replace(tzinfo=UTC)


def test_the_limit_is_64_mib() -> None:
    assert pdf_meta.INFLATE_LIMIT == 64 * 1024 * 1024
